const WHYP={h:L3("Why participation matters — and what abstention changes","Pourquoi la participation compte — et ce que change l'abstention","Por qué importa la participación y qué cambia la abstención"),
 lead:L3("Voting is one way to influence who represents you. The practical effect of voting, abstaining or casting a blank ballot depends on the country’s electoral rules. This page explains those effects and presents the case for taking part.","Voter est l'un des moyens d'influer sur qui vous représente. L'effet concret du vote, de l'abstention ou du vote blanc dépend des règles électorales de chaque pays. Cette page explique ces effets et présente les arguments en faveur de la participation.","Votar es una forma de influir en quién te representa. El efecto práctico de votar, abstenerse o votar en blanco depende de las reglas electorales de cada país. Esta página explica esos efectos y presenta los argumentos a favor de participar.")};
const RDIR={life:1,school:1,cpi:1,hom:-1};
const RLX={above:L3("Above the reference","Au-dessus de la référence","Por encima de la referencia"),close:L3("Close to the reference","Proche de la référence","Cerca de la referencia"),below:L3("Below the reference","En dessous de la référence","Por debajo de la referencia"),hi:L3("Upper part of the scale","Haut de l'échelle","Parte alta de la escala"),md:L3("Middle of the scale","Milieu de l'échelle","Mitad de la escala"),lo:L3("Lower part of the scale","Bas de l'échelle","Parte baja de la escala")};
const RWX={above:L3("above","au-dessus","por encima"),close:L3("close","proche","cerca"),below:L3("below","en dessous","por debajo"),hi:L3("upper part","haut de l'échelle","parte alta"),md:L3("middle","milieu","mitad"),lo:L3("lower part","bas de l'échelle","parte baja")};
function rateWord(mk,m,long){if(!m||m.rate==="na"||m.main==="—")return "";const d=RDIR[mk],r=m.rate;const k=d?(r==="mid"?"close":(r==="good")===(d>0)?"above":"below"):(r==="good"?"hi":r==="bad"?"lo":"md");return tr((long?RLX:RWX)[k])}
const CONT_NOTE=L3("Continents follow the UN M49 standard, a statistical convention that implies no political affiliation.","Continents selon le standard M49 de l'ONU, une convention statistique qui ne présume d'aucune appartenance politique.","Continentes según el estándar M49 de la ONU, una convención estadística que no presupone ninguna pertenencia política.");
const CIND={h:L3("Indicators shown","Indicateurs affichés","Indicadores mostrados")};
function cmpLegend(){return `<div class="rlegend">${[["good",L3("More favourable on this indicator","Plus favorable sur cet indicateur","Más favorable en este indicador")],["mid",L3("Close to the reference, or middle of the scale","Proche de la référence, ou milieu de l'échelle","Cerca de la referencia, o mitad de la escala")],["bad",L3("Less favourable on this indicator","Moins favorable sur cet indicateur","Menos favorable en este indicador")]].map(([r,l])=>`<span class="rdot r-${r}">${tr(l)}</span>`).join("")}</div><p class="rnote">${tr(L3("These labels compare a country with the reference shown for that indicator. They do not rate a country overall. Whether a higher value is favourable depends on the indicator: a higher life expectancy is, a higher homicide rate is not.","Ces repères comparent un pays à la référence indiquée pour chaque indicateur. Ils ne notent pas un pays dans son ensemble. Qu'une valeur plus élevée soit favorable dépend de l'indicateur : une espérance de vie plus haute l'est, un taux d'homicides plus haut ne l'est pas.","Estas etiquetas comparan un país con la referencia indicada para cada indicador. No califican al país en su conjunto. Que un valor más alto sea favorable depende del indicador: una esperanza de vida más alta lo es; una tasa de homicidios más alta, no."))}</p>`}
function cmpCols(box){box.querySelectorAll("[data-ci]").forEach(b=>{const on=b.getAttribute("aria-pressed")==="true";box.querySelectorAll(`[data-mk="${b.dataset.ci}"]`).forEach(c=>c.classList.toggle("colhide",!on))});tableScrollState()}
function cmpNarrow(){if(innerWidth>=760)return;document.querySelectorAll(".cind").forEach(g=>{if(g.dataset.init)return;g.dataset.init=1;const keep=["life","hom","rsf"];g.querySelectorAll("[data-ci]").forEach(b=>b.setAttribute("aria-pressed",String(keep.includes(b.dataset.ci))));cmpCols(g.parentNode)})}
document.addEventListener("click",e=>{const b=e.target.closest&&e.target.closest("[data-ci]");if(!b)return;const g=b.closest(".cind"),on=b.getAttribute("aria-pressed")==="true";if(on&&g.querySelectorAll('[aria-pressed="true"]').length<2)return;b.setAttribute("aria-pressed",String(!on));cmpCols(g.parentNode)});
