function pwaPlatform(){const u=navigator.userAgent;if(/iphone|ipad|ipod/i.test(u)||(navigator.platform==="MacIntel"&&navigator.maxTouchPoints>1))return "ios";if(/android/i.test(u))return "android";return "desktop"}
